INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein ERP-System immer für kleine Unternehmen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität oft für größere Firmen ausgelegt"}, {"text": "Ja", "correct": false, "because": "Kleine Firmen brauchen oft einfachere Lösungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines ERP-Systems ist für die Lagerverwaltung entscheidend?', 3, '[{"text": "Bestandsmanagement", "correct": true, "because": "Überwacht Lagerbestände"}, {"text": "Kundendatenbank", "correct": false, "because": "Für CRM relevant"}, {"text": "Textverarbeitung", "correct": false, "because": "Keine ERP-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ERP-Systeme integrieren verschiedene Geschäftsprozesse. b) Sie sind nur für die Finanzabteilung gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ERP ist unternehmensweit"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur für Finanzen"}, {"text": "Nur b) stimmt", "correct": false, "because": "ERP ist breiter gefächert"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal eines ERP-Systems solltest du für ein Produktionsunternehmen priorisieren?', 4, '[{"text": "Produktionsplanung", "correct": true, "because": "Optimiert Fertigungsprozesse"}, {"text": "E-Mail-Integration", "correct": false, "because": "Weniger relevant"}, {"text": "Design der Benutzeroberfläche", "correct": false, "because": "Sekundär zur Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein ERP-System ohne Internetverbindung genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Installationen sind möglich"}, {"text": "Nein", "correct": false, "because": "Internet oft nicht zwingend nötig"}]');
