INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein ERP-System immer für die Finanzbuchhaltung geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Finanzmodule sind Standard"}, {"text": "Nein", "correct": false, "because": "ERP umfasst meist Buchhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal eines ERP-Systems ist für die Supply-Chain-Optimierung entscheidend?', 3, '[{"text": "Lieferkettenmanagement", "correct": true, "because": "Koordiniert Beschaffung und Verteilung"}, {"text": "Textverarbeitung", "correct": false, "because": "Nicht ERP-spezifisch"}, {"text": "E-Mail-Funktion", "correct": false, "because": "Kein Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ERP-Systeme sind für alle Branchen gleich. b) Sie integrieren Geschäftsprozesse.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "ERP wird branchenspezifisch angepasst"}, {"text": "Nur b) stimmt", "correct": true, "because": "Integration ist Hauptzweck"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines ERP-Systems solltest du für ein Handelsunternehmen priorisieren?', 4, '[{"text": "Warenwirtschaft", "correct": true, "because": "Verwaltet Lager und Bestellungen"}, {"text": "Design der Oberfläche", "correct": false, "because": "Sekundär zur Funktion"}, {"text": "Kundenkontakte", "correct": false, "because": "Eher CRM-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein ERP-System ohne Schulung effektiv eingesetzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität erfordert Training"}, {"text": "Ja", "correct": false, "because": "Ohne Schulung ineffizient"}]');
